```js
import { authenticator } from 'otplib';
import { parse as parseUrl } from 'node:url';

const STEP_SECONDS = 30;
const SKEW_STEPS = 1;         // accept current ± 1 step: 3 valid windows
const MAX_STEPS = 2;          // hard cap — never accept a huge window

export async function verifyTotp(user, submitted) {
  if (!/^\d{6}$/.test(String(submitted ?? ''))) {
    await recordMfaFailure(user.id, 'malformed');
    return { ok: false, reason: 'malformed' };
  }
  const secret = await secrets.decryptTotp(user.totpSecretEnc);
  if (!secret) return { ok: false, reason: 'not_enrolled' };

  const key = authenticator.keyDecode(secret); // validate base32 length/format first
  if (key.length !== 20) return { ok: false, reason: 'bad_secret' };

  const nowStep = Math.floor(Date.now() / 1000 / STEP_SECONDS);
  // Compute all candidate steps ourselves so we can enforce a hard cap and burn them.
  for (let delta = -SKEW_STEPS; delta <= SKEW_STEPS; delta++) {
    const step = nowStep + delta;
    if (Math.abs(delta) > MAX_STEPS) break;
    const expected = hotp(key, step);
    if (timingSafeEqualStr(expected, submitted)) {
      // Replay protection: a code is valid for exactly one step, ever.
      const usedKey = `totp:used:${user.id}:${step}`;
      const first = await redis.set(usedKey, '1', 'NX', 'EX', STEP_SECONDS * 2);
      if (first) return { ok: true, step };
      return { ok: false, reason: 'code_replayed' };
    }
  }
  await recordMfaFailure(user.id, 'mismatch');
  return { ok: false, reason: 'mismatch' };
}

function hotp(key, counter) {
  const buf = Buffer.alloc(8);
  buf.writeBigUInt64BE(BigInt(counter));
  const h = createHmac('sha1', key).update(buf).digest();
  const offset = h[h.length - 1] & 0x0f;
  const bin = ((h[offset] & 0x7f) << 24) | (h[offset + 1] << 16) | (h[offset + 2] << 8) | h[offset + 3];
  return String(bin % 1_000_000).padStart(6, '0');
}
```

```
Registration: client creates a key pair (ideally in a hardware authenticator),
  sends attestation (optionally none), server stores:
    credentialId, publicKey (COSE), signCount, aaguid, transports, backupState,
    userVerified, attestationType, authenticatorData policy

Assertion:    server sends a WebAuthn challenge (>=16 random bytes, single use, ~5 min TTL)
  authenticator returns { authenticatorData, signature, userHandle }
  server verifies:
    1. challenge matches the stored, unexpired, unused challenge  -> else reject
    2. rpIdHash == SHA256(origin registrable domain suffix)         -> else reject
    3. flags UP (user present) set; UV required for privileged actions
    4. signature verifies under the stored public key over
       authenticatorData || SHA256(clientDataJSON)
    5. clientData.type == "webauthn.get" and .challenge == stored challenge
    6. clientData.origin == the exact expected origin
    7. signCount increased (detects cloned authenticators) when the authenticator is multi-device-capable
```

```js
import { verifyAuthenticationResponse } from '@simplewebauthn/server';

export async function verifyPasskeyAssertion({ credentialId, response, expectedChallenge, user }) {
  const stored = await credentials.get(user.id, credentialId);
  if (!stored) throw new AuthError('unknown_credential');

  const verification = await verifyAuthenticationResponse({
    response,
    expectedChallenge,                                  // string, single use
    expectedOrigin: 'https://app.example.com',          // exact; NOT derived from the request
    expectedRPID: 'example.com',                        // registrable domain suffix
    credential: {
      id: stored.credentialId,
      publicKey: Buffer.from(stored.publicKeyBase64url, 'base64url'),
      counter: stored.signCount,
      transports: stored.transports,
    },
    requireUserVerification: stored.uvRequired,
  });

  if (!verification.verified) throw new AuthError('assertion_failed');
  if (verification.authenticationInfo.newCounter <= stored.signCount
      && !stored.multiDeviceCapable) {
    throw new AuthError('possible_clone');  // counter went backwards
  }
  await credentials.updateCounter(stored.id, verification.authenticationInfo.newCounter);
  return verification.authenticationInfo;
}
