```js
import { authenticator } from 'otplib';
import { parse as parseUrl } from 'node:url';

const STEP_SECONDS = 30;
const SKEW_STEPS = 1;         // accept current ± 1 step: 3 valid windows
const MAX_STEPS = 2;          // hard cap — never accept a huge window

export async function verifyTotp(user, submitted) {
  if (!/^\d{6}$/.test(String(submitted ?? ''))) {
    await recordMfaFailure(user.id, 'malformed');
    return { ok: false, reason: 'malformed' };
  }
  const secret = await secrets.decryptTotp(user.totpSecretEnc);
  if (!secret) return { ok: false, reason: 'not_enrolled' };

  const key = authenticator.keyDecode(secret); // validate base32 length/format first
  if (key.length !== 20) return { ok: false, reason: 'bad_secret' };

  const nowStep = Math.floor(Date.now() / 1000 / STEP_SECONDS);
  // Compute all candidate steps ourselves so we can enforce a hard cap and burn them.
  for (let delta = -SKEW_STEPS; delta <= SKEW_STEPS; delta++) {
    const step = nowStep + delta;
    if (Math.abs(delta) > MAX_STEPS) break;
    const expected = hotp(key, step);
    if (timingSafeEqualStr(expected, submitted)) {
      // Replay protection: a code is valid for exactly one step, ever.
      const usedKey = `totp:used:${user.id}:${step}`;
      const first = await redis.set(usedKey, '1', 'NX', 'EX', STEP_SECONDS * 2);
      if (first) return { ok: true, step };
      return { ok: false, reason: 'code_replayed' };
    }
  }
  await recordMfaFailure(user.id, 'mismatch');
  return { ok: false, reason: 'mismatch' };
}

function hotp(key, counter) {
  const buf = Buffer.alloc(8);
  buf.writeBigUInt64BE(BigInt(counter));
  const h = createHmac('sha1', key).update(buf).digest();
  const offset = h[h.length - 1] & 0x0f;
  const bin = ((h[offset] & 0x7f) << 24) | (h[offset + 1] << 16) | (h[offset + 2] << 8) | h[offset + 3];
  return String(bin % 1_000_000).padStart(6, '0');
}
