```js
import { verifyAuthenticationResponse } from '@simplewebauthn/server';

export async function verifyPasskeyAssertion({ credentialId, response, expectedChallenge, user }) {
  const stored = await credentials.get(user.id, credentialId);
  if (!stored) throw new AuthError('unknown_credential');

  const verification = await verifyAuthenticationResponse({
    response,
    expectedChallenge,                                  // string, single use
    expectedOrigin: 'https://app.example.com',          // exact; NOT derived from the request
    expectedRPID: 'example.com',                        // registrable domain suffix
    credential: {
      id: stored.credentialId,
      publicKey: Buffer.from(stored.publicKeyBase64url, 'base64url'),
      counter: stored.signCount,
      transports: stored.transports,
    },
    requireUserVerification: stored.uvRequired,
  });

  if (!verification.verified) throw new AuthError('assertion_failed');
  if (verification.authenticationInfo.newCounter <= stored.signCount
      && !stored.multiDeviceCapable) {
    throw new AuthError('possible_clone');  // counter went backwards
  }
  await credentials.updateCounter(stored.id, verification.authenticationInfo.newCounter);
  return verification.authenticationInfo;
}
