export function requireMfaFresness(req, res, next) {
  const s = req.session;
  if (!s) return res.status(401).json({ error: 'unauthenticated' });

  const now = Date.now();
  const mfaAt = s.mfaVerifiedAt ?? 0;

  // Explicit: require a *fresh* factor, regardless of session age
  if (mfaAt < now - 5 * 60_000) {
    return res.status(403).json({ error: 'step_up_required', reason: 'mfa_stale' });
  }
  // Or: require a session authenticated with a high assurance level
  if (s.amr && !s.amr.includes('mfa') && !s.amr.includes('hwk')) {
    return res.status(403).json({ error: 'step_up_required', reason: 'assurance_too_low' });
  }
  next();
}

// Routes requiring step-up: password change, email change, MFA enrollment,
// session revocation, API key creation, exports, PII views, payouts.
