```js
import crypto from 'node:crypto';

const PREFIX_ALPHABET = 'ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz23456789'; // no I,l,O,0

export function generateApiKey(env = 'live') {
  const prefix = Array.from(crypto.randomBytes(8))
    .map((b) => PREFIX_ALPHABET[b % PREFIX_ALPHABET.length]).join('');
  const secret = crypto.randomBytes(32).toString('base64url');
  const key = `sk_${env}_${prefix}_${secret}`;
  return { key, prefix, env, secretHash: hashSecret(secret) };
}

function hashSecret(secret) {
  // HMAC with a server-side pepper: a DB dump alone yields no usable keys.
  return crypto.createHmac('sha256', process.env.API_KEY_PEPPER)
    .update(secret).digest('base64url');
}

export function parseApiKey(raw) {
  const m = /^sk_([a-z]+)_([A-Za-z0-9]{8})_([A-Za-z0-9_-]{20,})$/.exec(String(raw ?? ''));
  if (!m) return null;
  return { env: m[1], prefix: m[2], secret: m[3] };
}

export async function authenticateApiKey(raw, { requiredScopes = [] } = {}) {
  const parsed = parseApiKey(raw);
  if (!parsed) return { ok: false, reason: 'malformed' };
  if (parsed.env !== process.env.APP_ENV) return { ok: false, reason: 'wrong_env' };

  const record = await apiKeys.findByPrefix(parsed.prefix); // indexed, no full scan
  if (!record) return { ok: false, reason: 'unknown_key' };
  if (record.revokedAt) return { ok: false, reason: 'revoked' };
  if (record.expiresAt && record.expiresAt < Date.now()) return { ok: false, reason: 'expired' };

  const expected = Buffer.from(record.secretHash);
  const got = Buffer.from(hashSecret(parsed.secret));
  if (expected.length !== got.length || !crypto.timingSafeEqual(expected, got)) {
    await apiKeys.recordFailedAttempt(record.id);
    return { ok: false, reason: 'mismatch' };
  }

  const granted = new Set(record.scopes);
  const missing = requiredScopes.filter((s) => !granted.has(s));
  if (missing.length) return { ok: false, reason: 'insufficient_scope', missing };

  return { ok: true, keyId: record.id, owner: record.ownerId, tenantId: record.tenantId, scopes: granted };
}
