export async function eraseSubject(subjectId, { reason = 'user_request', actor } = {}) {
  const plan = new ErasurePlan(subjectId);
  for (const [store, op] of Object.entries(SUBJECT_STORES)) {
    plan.add({ store, op, run: () => op(subjectId) });
  }
  const results = await plan.runAllWithRetries();
  const failures = results.filter((r) => !r.ok);
  if (failures.length) {
    // Do not report success. Queue for manual handling and alert.
    await erasureQueue.add({ subjectId, failures, reason, actor });
    await alerts.raise('gdpr.erasure_partial', { subjectId, failures });
